exec('\nfrom __future__ import annotations\nimport time, warnings, json, re\nfrom pathlib import Path\nfrom datetime import datetime, timezone, timedelta\nimport numpy as np\nimport pandas as pd\nimport streamlit as st\nimport yfinance as yf\nimport requests\nfrom sklearn.linear_model import Ridge\nfrom sklearn.ensemble import RandomForestRegressor\nfrom sklearn.metrics import mean_squared_error\n\nwarnings.filterwarnings("ignore")\nROOT = Path(__file__).resolve().parents[1]\n\nDEFAULT_ASSETS = ["XME","COPX","PICK","XLB","ITA","XAR","XLI","VIS","PRNT","DDD","SSYS","MTLS","NNDM","SOXX","SPY","EEM","URTH"]\nDEFAULT_COMMODITIES = {\n    "Copper": {"ticker":"HG=F","family":"industrial_metals","weight":0.16,"role":"industrial demand / electrification"},\n    "Aluminum": {"ticker":"ALI=F","family":"industrial_metals","weight":0.12,"role":"energy-intensive manufacturing"},\n    "IronOre": {"ticker":"TIO=F","family":"steel_chain","weight":0.08,"role":"steel / China construction proxy"},\n    "Steel": {"ticker":"SLX","family":"steel_chain","weight":0.08,"role":"steel producer ETF proxy"},\n    "Lithium": {"ticker":"LIT","family":"battery_materials","weight":0.08,"role":"battery supply-chain proxy"},\n    "RareEarths": {"ticker":"REMX","family":"critical_minerals","weight":0.10,"role":"rare earths / magnets / defense"},\n    "Uranium": {"ticker":"URA","family":"energy_security","weight":0.08,"role":"nuclear / energy security"},\n    "Oil": {"ticker":"CL=F","family":"energy_inputs","weight":0.13,"role":"transport / energy / geopolitics"},\n    "NaturalGas": {"ticker":"NG=F","family":"energy_inputs","weight":0.09,"role":"energy-intensive production"},\n    "Gold": {"ticker":"GC=F","family":"precious_stress","weight":0.08,"role":"safe haven / geopolitical stress"},\n    "Silver": {"ticker":"SI=F","family":"precious_stress","weight":0.05,"role":"precious + industrial hybrid"},\n    "Platinum": {"ticker":"PL=F","family":"precious_industrial","weight":0.04,"role":"auto catalyst / industrial"},\n    "Palladium": {"ticker":"PA=F","family":"precious_industrial","weight":0.04,"role":"auto catalyst / supply stress"},\n}\nGLOBAL_INDICES = {\n    "USA": {"SP500":"^GSPC","Nasdaq100":"^NDX","Russell2000":"^RUT","DowJones":"^DJI","Semiconductors":"SOXX","Industrials":"XLI","Materials":"XLB","Energy":"XLE"},\n    "Europe": {"DAX":"^GDAXI","CAC40":"^FCHI","FTSE100":"^FTSE","FTSEMIB":"FTSEMIB.MI","EuropeETF":"VGK"},\n    "China/HK": {"CSI300":"000300.SS","SSE":"000001.SS","HangSeng":"^HSI","ChinaLargeCap":"FXI"},\n    "Japan": {"Nikkei225":"^N225","TopixETF":"1306.T","JapanETF":"EWJ"},\n    "Global": {"WorldProxy":"URTH","EmergingMarkets":"EEM","GlobalIndustrials":"EXI"},\n}\nMACRO = {"USDIndex":"DX-Y.NYB","US10Y":"^TNX","ShortRate":"^IRX","TIPS":"TIP","HighYield":"HYG","InvestmentGrade":"LQD","EURUSD":"EURUSD=X","USDCNY":"CNY=X","USDJPY":"JPY=X","VIX":"^VIX","FreightProxy":"BDRY"}\nEXPOSURE_FALLBACK = pd.DataFrame([\n    {"asset":"XME","theme":"Mining/metals","copper":.7,"aluminum":.5,"nickel":.4,"steel_chain":.8,"battery":.2,"rare_earths":.2,"energy":.5,"uranium":.1,"aerospace":.1,"defense":.1,"additive_manufacturing":0,"china_sensitivity":.5,"macro_beta":.7},\n    {"asset":"COPX","theme":"Copper miners","copper":1,"aluminum":.2,"nickel":.1,"steel_chain":.2,"battery":.1,"rare_earths":.1,"energy":.3,"uranium":0,"aerospace":0,"defense":0,"additive_manufacturing":0,"china_sensitivity":.6,"macro_beta":.7},\n    {"asset":"PICK","theme":"Global mining","copper":.6,"aluminum":.5,"nickel":.5,"steel_chain":.8,"battery":.3,"rare_earths":.2,"energy":.5,"uranium":.1,"aerospace":0,"defense":0,"additive_manufacturing":0,"china_sensitivity":.6,"macro_beta":.7},\n    {"asset":"XLB","theme":"Materials","copper":.4,"aluminum":.5,"nickel":.2,"steel_chain":.4,"battery":.2,"rare_earths":.1,"energy":.5,"uranium":0,"aerospace":.1,"defense":0,"additive_manufacturing":0,"china_sensitivity":.3,"macro_beta":.7},\n    {"asset":"ITA","theme":"Defense/aerospace","copper":.1,"aluminum":.6,"nickel":.5,"steel_chain":.3,"battery":.1,"rare_earths":.4,"energy":.6,"uranium":.1,"aerospace":1,"defense":1,"additive_manufacturing":.1,"china_sensitivity":.2,"macro_beta":.6},\n    {"asset":"XAR","theme":"Aerospace supply chain","copper":.2,"aluminum":.7,"nickel":.5,"steel_chain":.4,"battery":.1,"rare_earths":.3,"energy":.6,"uranium":.1,"aerospace":1,"defense":.8,"additive_manufacturing":.1,"china_sensitivity":.2,"macro_beta":.7},\n    {"asset":"XLI","theme":"Industrials","copper":.3,"aluminum":.4,"nickel":.2,"steel_chain":.4,"battery":.1,"rare_earths":.1,"energy":.6,"uranium":0,"aerospace":.4,"defense":.2,"additive_manufacturing":.1,"china_sensitivity":.3,"macro_beta":.8},\n    {"asset":"PRNT","theme":"Additive manufacturing","copper":.3,"aluminum":.4,"nickel":.3,"steel_chain":.2,"battery":.2,"rare_earths":.2,"energy":.4,"uranium":0,"aerospace":.3,"defense":.2,"additive_manufacturing":1,"china_sensitivity":.3,"macro_beta":.8},\n    {"asset":"DDD","theme":"Additive manufacturing","copper":.3,"aluminum":.4,"nickel":.3,"steel_chain":.2,"battery":.2,"rare_earths":.2,"energy":.4,"uranium":0,"aerospace":.3,"defense":.1,"additive_manufacturing":1,"china_sensitivity":.3,"macro_beta":.9},\n    {"asset":"SSYS","theme":"Additive manufacturing","copper":.3,"aluminum":.4,"nickel":.3,"steel_chain":.2,"battery":.2,"rare_earths":.2,"energy":.4,"uranium":0,"aerospace":.3,"defense":.1,"additive_manufacturing":1,"china_sensitivity":.3,"macro_beta":.9},\n    {"asset":"MTLS","theme":"Digital manufacturing","copper":.2,"aluminum":.3,"nickel":.2,"steel_chain":.1,"battery":.1,"rare_earths":.1,"energy":.3,"uranium":0,"aerospace":.2,"defense":.1,"additive_manufacturing":.9,"china_sensitivity":.2,"macro_beta":.8},\n    {"asset":"NNDM","theme":"Advanced electronics/AM","copper":.3,"aluminum":.2,"nickel":.2,"steel_chain":.1,"battery":.3,"rare_earths":.2,"energy":.2,"uranium":0,"aerospace":.2,"defense":.1,"additive_manufacturing":.8,"china_sensitivity":.4,"macro_beta":1},\n    {"asset":"SOXX","theme":"Semiconductors","copper":.3,"aluminum":.2,"nickel":.1,"steel_chain":.1,"battery":.3,"rare_earths":.6,"energy":.2,"uranium":0,"aerospace":.1,"defense":.3,"additive_manufacturing":.1,"china_sensitivity":.8,"macro_beta":1},\n    {"asset":"SPY","theme":"US benchmark","copper":.2,"aluminum":.2,"nickel":.1,"steel_chain":.2,"battery":.1,"rare_earths":.1,"energy":.3,"uranium":0,"aerospace":.2,"defense":.1,"additive_manufacturing":.1,"china_sensitivity":.2,"macro_beta":1},\n    {"asset":"EEM","theme":"Emerging markets","copper":.5,"aluminum":.4,"nickel":.3,"steel_chain":.4,"battery":.3,"rare_earths":.3,"energy":.5,"uranium":.1,"aerospace":.1,"defense":.1,"additive_manufacturing":.1,"china_sensitivity":.8,"macro_beta":.9},\n    {"asset":"URTH","theme":"Global equities","copper":.2,"aluminum":.2,"nickel":.1,"steel_chain":.2,"battery":.1,"rare_earths":.1,"energy":.3,"uranium":0,"aerospace":.2,"defense":.1,"additive_manufacturing":.1,"china_sensitivity":.3,"macro_beta":1},\n])\n\ndef load_yaml(path, fallback):\n    try:\n        import yaml\n        p = ROOT / path\n        if p.exists():\n            return yaml.safe_load(p.read_text(encoding="utf-8")) or fallback\n    except Exception:\n        pass\n    return fallback\n\ndef load_exposure():\n    p = ROOT / "data" / "exposure_score_table.csv"\n    try:\n        if p.exists():\n            return pd.read_csv(p)\n    except Exception:\n        pass\n    return EXPOSURE_FALLBACK.copy()\n\ndef flatten_index_map(idx_config):\n    rows = []\n    for region, mp in idx_config.items():\n        for name, ticker in mp.items():\n            rows.append({"region": region, "name": name, "ticker": ticker})\n    return pd.DataFrame(rows)\n\ndef safe_period(interval, period):\n    if interval == "1m":\n        return period if period in ["1d","5d"] else "5d"\n    if interval in ["5m","15m","30m","60m"]:\n        return period if period in ["1d","5d","1mo"] else "1mo"\n    return period\n\n@st.cache_data(ttl=60, show_spinner=False)\ndef download_prices(tickers, period, interval):\n    tickers = sorted([t for t in set(tickers) if isinstance(t, str) and t.strip()])\n    raw = yf.download(tickers, period=period, interval=interval, auto_adjust=True, progress=False, threads=False)\n    if raw.empty:\n        return pd.DataFrame()\n    if isinstance(raw.columns, pd.MultiIndex):\n        if "Close" in raw.columns.get_level_values(0):\n            prices = raw["Close"].copy()\n        else:\n            prices = raw.xs("Close", axis=1, level=1, drop_level=True).copy()\n    else:\n        prices = raw[["Close"]].copy()\n        if len(tickers) == 1:\n            prices.columns = tickers\n    prices = prices.dropna(axis=1, how="all").ffill().dropna(how="all")\n    return prices\n\ndef zscore(s, window):\n    mean = s.rolling(window, min_periods=max(5, window//3)).mean()\n    std = s.rolling(window, min_periods=max(5, window//3)).std()\n    return (s - mean) / std\n\ndef build_features(prices, materials, macro, shock_window):\n    features = pd.DataFrame(index=prices.index)\n    meta = []\n    for name, spec in materials.items():\n        ticker = spec.get("ticker")\n        if ticker in prices.columns:\n            ret = prices[ticker].pct_change(shock_window)\n            col = f"MATERIAL_{name}_shock"\n            features[col] = zscore(ret, max(20, shock_window*4))\n            meta.append({"feature": col, "name": name, "ticker": ticker, "family": spec.get("family","unknown"), "weight": float(spec.get("weight", 0.05)), "role": spec.get("role","")})\n    for name, ticker in macro.items():\n        if ticker in prices.columns:\n            ret = prices[ticker].pct_change(shock_window)\n            col = f"MACRO_{name}_shock"\n            features[col] = zscore(ret, max(20, shock_window*4))\n            meta.append({"feature": col, "name": name, "ticker": ticker, "family": "macro", "weight": 0.05, "role": "macro/market stress"})\n    if features.empty:\n        return features, pd.DataFrame(meta)\n    meta_df = pd.DataFrame(meta)\n    weighted = []\n    total = 0.0\n    for _, r in meta_df.iterrows():\n        if r["feature"] in features.columns:\n            w = float(r["weight"])\n            weighted.append(features[r["feature"]] * w)\n            total += w\n    features["GCMSI_Global_Critical_Materials_Stress"] = sum(weighted) / total if weighted and total > 0 else features.mean(axis=1)\n    for fam in meta_df["family"].dropna().unique():\n        cols = meta_df.loc[meta_df["family"] == fam, "feature"].tolist()\n        cols = [c for c in cols if c in features.columns]\n        if cols:\n            features[f"FAMILY_{fam}_stress"] = features[cols].mean(axis=1)\n    if "MACRO_VIX_shock" in features and "GCMSI_Global_Critical_Materials_Stress" in features:\n        features["REGIME_RiskOff_Materials"] = (features["MACRO_VIX_shock"] + features["GCMSI_Global_Critical_Materials_Stress"]) / 2\n    return features.replace([np.inf,-np.inf], np.nan).dropna(), meta_df\n\ndef classify_regime(features):\n    latest = features.iloc[-1]\n    gcmsi = latest.get("GCMSI_Global_Critical_Materials_Stress", 0)\n    vix = latest.get("MACRO_VIX_shock", 0)\n    usd = latest.get("MACRO_USDIndex_shock", 0)\n    energy = latest.get("FAMILY_energy_inputs_stress", 0)\n    steel = latest.get("FAMILY_steel_chain_stress", 0)\n    crit = latest.get("FAMILY_critical_minerals_stress", 0)\n    if gcmsi > 1.5 and vix > 1.0:\n        return "Risk-off industrial stress"\n    if energy > 1.2:\n        return "Energy-cost shock"\n    if usd > 1.2 and gcmsi > 0.5:\n        return "USD / commodity pressure"\n    if steel < -1.0 and crit < -0.5:\n        return "Industrial slowdown / demand stress"\n    if gcmsi > 1.0:\n        return "Commodity shock"\n    if gcmsi < -1.0:\n        return "Materials stress easing"\n    return "Normal / mixed"\n\ndef stress_label(x):\n    if x >= 2: return "Critical", "Global critical-materials stress is extreme."\n    if x >= 1: return "Elevated", "Global critical-materials stress is above normal."\n    if x <= -1: return "Easing", "Materials/macro stress is below normal."\n    return "Normal", "No major materials stress signal."\n\ndef forward_return(prices, asset, horizon):\n    return prices[asset].pct_change(horizon).shift(-horizon).rename("future_return")\n\ndef train_predict_asset(asset, prices, features, horizon, model_name, feature_cols):\n    if asset not in prices.columns:\n        return None, None, "missing price"\n    y = forward_return(prices, asset, horizon)\n    df = pd.concat([features[feature_cols], y], axis=1, join="inner").dropna()\n    if len(df) < 90:\n        return None, None, "not enough rows"\n    split = int(len(df) * 0.75)\n    train, test = df.iloc[:split], df.iloc[split:]\n    Xtr, ytr = train[feature_cols].fillna(0), train["future_return"].astype(float)\n    Xte, yte = test[feature_cols].fillna(0), test["future_return"].astype(float)\n    model = RandomForestRegressor(n_estimators=200, max_depth=4, random_state=42) if model_name == "RandomForest" else Ridge(alpha=10.0)\n    model.fit(Xtr, ytr)\n    pred_test = model.predict(Xte)\n    latest_pred = float(model.predict(features.iloc[[-1]][feature_cols].fillna(0))[0])\n    rmse = float(mean_squared_error(yte, pred_test) ** 0.5)\n    corr = pd.Series(pred_test).corr(pd.Series(yte.values))\n    corr = 0.0 if pd.isna(corr) else float(corr)\n    vol = float(ytr.std()) if ytr.std() > 0 else 1.0\n    confidence = min(abs(latest_pred) / vol, 2.0) / 2.0\n    if hasattr(model, "feature_importances_"):\n        imp = pd.Series(model.feature_importances_, index=feature_cols).sort_values(ascending=False)\n    else:\n        imp = pd.Series(np.abs(getattr(model, "coef_", np.zeros(len(feature_cols)))), index=feature_cols).sort_values(ascending=False)\n    test_df = test.copy()\n    test_df["prediction"] = pred_test\n    test_df["position"] = np.where(test_df["prediction"] > 0, 1.0, -1.0)\n    test_df["strategy_return"] = test_df["position"] * test_df["future_return"]\n    test_df["equity"] = (1 + test_df["strategy_return"].fillna(0)).cumprod()\n    result = {\n        "asset": asset,\n        "latest_prediction": latest_pred,\n        "direction": "positive" if latest_pred > 0 else "negative",\n        "confidence_0_1": confidence,\n        "test_corr": corr,\n        "rmse": rmse,\n        "train_rows": len(train),\n        "test_rows": len(test),\n        "top_driver_1": imp.index[0] if len(imp) else "",\n        "top_driver_2": imp.index[1] if len(imp) > 1 else "",\n        "top_driver_3": imp.index[2] if len(imp) > 2 else "",\n    }\n    return result, test_df, None\n\ndef make_warnings(row, exposure_row, regime):\n    if row is None:\n        return "No prediction."\n    msgs = []\n    pred = row["latest_prediction"]\n    if pred < 0 and row["confidence_0_1"] > 0.4:\n        msgs.append("negative pressure")\n    if pred > 0 and row["confidence_0_1"] > 0.4:\n        msgs.append("positive pressure")\n    if exposure_row is not None:\n        if exposure_row.get("copper",0) > 0.6:\n            msgs.append("copper-sensitive")\n        if exposure_row.get("aerospace",0) > 0.6:\n            msgs.append("aerospace-sensitive")\n        if exposure_row.get("additive_manufacturing",0) > 0.6:\n            msgs.append("AM-sensitive")\n        if exposure_row.get("china_sensitivity",0) > 0.6:\n            msgs.append("China-sensitive")\n    msgs.append(regime)\n    return " | ".join(msgs)\n\n@st.cache_data(ttl=300, show_spinner=False)\ndef fetch_gdelt_news(query, max_records=20):\n    try:\n        url = "https://api.gdeltproject.org/api/v2/doc/doc"\n        params = {"query": query, "mode": "ArtList", "format": "json", "maxrecords": max_records, "sort": "HybridRel"}\n        r = requests.get(url, params=params, timeout=12)\n        if r.status_code != 200:\n            return pd.DataFrame()\n        data = r.json()\n        arts = data.get("articles", [])\n        rows = []\n        for a in arts:\n            rows.append({\n                "title": a.get("title",""),\n                "source": a.get("sourceCountry",""),\n                "url": a.get("url",""),\n                "domain": a.get("domain",""),\n                "seendate": a.get("seendate",""),\n            })\n        return pd.DataFrame(rows)\n    except Exception:\n        return pd.DataFrame()\n\ndef geo_risk_score(news_df, keyword_config):\n    if news_df.empty:\n        return 0.0, pd.DataFrame()\n    text = " ".join(news_df["title"].fillna("").astype(str).tolist()).lower()\n    themes = keyword_config.get("themes", {})\n    rows = []\n    total = 0\n    for theme, words in themes.items():\n        count = 0\n        for w in words:\n            count += text.count(str(w).lower())\n        total += count\n        rows.append({"theme": theme, "mentions": count})\n    score = min(total / 10, 3.0)\n    return score, pd.DataFrame(rows).sort_values("mentions", ascending=False)\n\ndef normalize_prices(prices):\n    x = prices.dropna(how="all").ffill()\n    return x / x.iloc[0]\n\n# ---------------- App ----------------\nst.set_page_config(page_title="MatQuantLab V4", layout="wide")\nst.title("MatQuantLab V4 — Global Critical Materials Intelligence")\nst.caption("Industrial stress radar, global macro/materials map, geopolitical news, exposure matrix, regime detection, and prediction tool for all assets.")\n\nmaterials_cfg = load_yaml("config/materials_universe.yml", {"materials": DEFAULT_COMMODITIES}).get("materials", DEFAULT_COMMODITIES)\nindices_cfg = load_yaml("config/global_index_config.yml", {"indices": GLOBAL_INDICES}).get("indices", GLOBAL_INDICES)\nmacro_cfg = load_yaml("config/macro_series_config.yml", {"macro_proxies": {k: {"ticker": v} for k,v in MACRO.items()}}).get("macro_proxies", {k: {"ticker": v} for k,v in MACRO.items()})\ngeo_cfg = load_yaml("config/geopolitical_keywords.yml", {"themes": {}, "default_query": "critical minerals OR rare earth OR sanctions OR export controls"})\nexposure = load_exposure()\n\nmacro_tickers = {k: v.get("ticker", v) if isinstance(v, dict) else v for k,v in macro_cfg.items()}\nall_index_df = flatten_index_map(indices_cfg)\nall_index_tickers = all_index_df["ticker"].dropna().astype(str).tolist()\ntarget_assets = sorted(set(exposure["asset"].astype(str).tolist() + DEFAULT_ASSETS))\n\nwith st.sidebar:\n    st.header("V4 Controls")\n    selected_assets = st.multiselect("Prediction assets", target_assets, default=[a for a in ["XME","COPX","ITA","XAR","PRNT","SOXX","SPY","EEM"] if a in target_assets])\n    interval = st.selectbox("Interval", ["1m","5m","15m","30m","60m","1d"], index=1)\n    period = st.selectbox("Period", ["1d","5d","1mo","3mo","6mo","1y"], index=1)\n    model_name = st.selectbox("Prediction model", ["Ridge","RandomForest"])\n    horizon = st.slider("Prediction horizon in bars", 1, 120, 12)\n    shock_window = st.slider("Shock window in bars", 3, 80, 20)\n    news_query = st.text_area("Geopolitical news query", value=geo_cfg.get("default_query","critical minerals OR rare earth OR sanctions OR export controls"), height=90)\n    if st.button("Refresh all data"):\n        st.cache_data.clear()\n        st.rerun()\n    auto = st.toggle("Auto-refresh every 60 seconds", value=False)\n\nif auto:\n    time.sleep(60)\n    st.cache_data.clear()\n    st.rerun()\n\nperiod = safe_period(interval, period)\nmaterial_tickers = [spec.get("ticker") for spec in materials_cfg.values() if isinstance(spec, dict)]\ntickers = sorted(set(selected_assets + material_tickers + list(macro_tickers.values()) + all_index_tickers))\nprices = download_prices(tickers, period, interval)\nif prices.empty:\n    st.error("No data downloaded. Try a longer period, larger interval, or fewer tickers.")\n    st.stop()\nfeatures, feature_meta = build_features(prices, materials_cfg, macro_tickers, shock_window)\nif features.empty:\n    st.error("No features could be built. Try daily interval or longer period.")\n    st.stop()\n\nregime = classify_regime(features)\ngcmsi = float(features["GCMSI_Global_Critical_Materials_Stress"].iloc[-1])\nstress_state, stress_desc = stress_label(gcmsi)\n\nnews_df = fetch_gdelt_news(news_query, max_records=20)\ngeo_score, geo_theme_df = geo_risk_score(news_df, geo_cfg)\ngeo_state = "Critical" if geo_score >= 2.5 else "High" if geo_score >= 1.5 else "Elevated" if geo_score >= 0.7 else "Normal"\n\nprediction_feature_cols = [c for c in features.columns if c.startswith("MATERIAL_") or c.startswith("MACRO_") or c.startswith("FAMILY_") or c.startswith("REGIME_") or c.startswith("GCMSI_")]\n\npred_rows = []\ntest_curves = {}\nfor asset in selected_assets:\n    res, test_df, err = train_predict_asset(asset, prices, features, horizon, model_name, prediction_feature_cols)\n    if res:\n        exp_row_df = exposure.loc[exposure["asset"].astype(str) == asset]\n        exp_dict = exp_row_df.iloc[0].to_dict() if len(exp_row_df) else None\n        res["warning_summary"] = make_warnings(res, exp_dict, regime)\n        pred_rows.append(res)\n        test_curves[asset] = test_df\npred_df = pd.DataFrame(pred_rows)\nif not pred_df.empty:\n    pred_df = pred_df.sort_values(["confidence_0_1","latest_prediction"], ascending=[False, False])\n\nk1,k2,k3,k4,k5 = st.columns(5)\nk1.metric("GCMSI", f"{gcmsi:.2f}")\nk2.metric("Materials stress", stress_state)\nk3.metric("Regime", regime)\nk4.metric("Geo risk", geo_state)\nk5.metric("Assets predicted", len(pred_df))\nst.info(stress_desc)\n\ntabs = st.tabs([\n    "Executive Radar",\n    "Prediction Tool for All",\n    "Material Exposure Matrix",\n    "Global Stress Map",\n    "Geopolitical News",\n    "Regime Detection",\n    "Validation / Backtest",\n    "Raw Data",\n])\n\nwith tabs[0]:\n    st.subheader("Executive Industrial Stress Radar")\n    cols = [c for c in ["GCMSI_Global_Critical_Materials_Stress","FAMILY_industrial_metals_stress","FAMILY_steel_chain_stress","FAMILY_energy_inputs_stress","FAMILY_critical_minerals_stress","FAMILY_macro_stress"] if c in features.columns]\n    st.line_chart(features[cols])\n    st.markdown("### Current strongest stress drivers")\n    latest = features.iloc[-1]\n    driver_cols = [c for c in features.columns if c.startswith("MATERIAL_") or c.startswith("MACRO_")]\n    drivers = latest[driver_cols].sort_values(key=lambda s: s.abs(), ascending=False).head(15)\n    st.dataframe(drivers.rename("latest_z_score").to_frame(), use_container_width=True)\n    st.markdown("### System message")\n    st.write("MatQuantLab is not a stock-prediction app. It is a materials-informed industrial stress radar that tests whether metals, energy, USD, volatility, macro, and geopolitical stress can give early warnings for industrial assets.")\n\nwith tabs[1]:\n    st.subheader("Prediction Tool for All Selected Assets")\n    st.write("This table trains one research model per selected asset and predicts the latest horizon pressure.")\n    if pred_df.empty:\n        st.warning("No predictions. Try longer period / daily interval / fewer tickers.")\n    else:\n        show_cols = ["asset","direction","latest_prediction","confidence_0_1","test_corr","rmse","top_driver_1","top_driver_2","top_driver_3","warning_summary"]\n        st.dataframe(pred_df[show_cols], use_container_width=True)\n        chosen = st.selectbox("Explain asset", pred_df["asset"].tolist())\n        row = pred_df.loc[pred_df["asset"] == chosen].iloc[0]\n        st.markdown(f"### {chosen} explanation")\n        st.write(f"Direction: **{row[\'direction\']}**")\n        st.write(f"Latest prediction: `{row[\'latest_prediction\']:.5f}`")\n        st.write(f"Confidence: `{row[\'confidence_0_1\']:.2f}`")\n        st.write(f"Top drivers: `{row[\'top_driver_1\']}`, `{row[\'top_driver_2\']}`, `{row[\'top_driver_3\']}`")\n        st.write(f"Warning summary: {row[\'warning_summary\']}")\n\nwith tabs[2]:\n    st.subheader("Material Exposure Matrix")\n    st.write("This matrix is the bridge between materials engineering and quant finance.")\n    st.dataframe(exposure, use_container_width=True)\n    numeric_cols = [c for c in exposure.columns if c not in ["asset","theme"]]\n    if numeric_cols:\n        st.bar_chart(exposure.set_index("asset")[numeric_cols])\n    st.markdown("### Exposure-adjusted stress score")\n    stress_map = {\n        "copper": latest.get("MATERIAL_Copper_shock", 0),\n        "aluminum": latest.get("MATERIAL_Aluminum_shock", 0),\n        "nickel": latest.get("MATERIAL_Nickel_shock", 0),\n        "steel_chain": latest.get("FAMILY_steel_chain_stress", 0),\n        "battery": latest.get("FAMILY_battery_materials_stress", 0),\n        "rare_earths": latest.get("FAMILY_critical_minerals_stress", 0),\n        "energy": latest.get("FAMILY_energy_inputs_stress", 0),\n        "uranium": latest.get("MATERIAL_Uranium_shock", 0),\n        "aerospace": latest.get("FAMILY_industrial_metals_stress", 0),\n        "defense": geo_score,\n        "additive_manufacturing": latest.get("GCMSI_Global_Critical_Materials_Stress", 0),\n        "china_sensitivity": latest.get("MACRO_USDCNY_shock", 0),\n        "macro_beta": latest.get("FAMILY_macro_stress", 0),\n    }\n    scores = []\n    for _, r in exposure.iterrows():\n        score = 0\n        denom = 0\n        for k,v in stress_map.items():\n            if k in r:\n                score += float(r[k]) * float(v)\n                denom += abs(float(r[k]))\n        scores.append({"asset": r["asset"], "theme": r.get("theme",""), "exposure_adjusted_stress": score / denom if denom else 0})\n    st.dataframe(pd.DataFrame(scores).sort_values("exposure_adjusted_stress", ascending=False), use_container_width=True)\n\nwith tabs[3]:\n    st.subheader("Global Stress Map")\n    st.markdown("### Global indices normalized")\n    available_indices = [t for t in all_index_tickers if t in prices.columns]\n    if available_indices:\n        # Avoid too crowded\n        st.line_chart(normalize_prices(prices[available_indices[:20]]))\n    else:\n        st.warning("No global indices available in downloaded data.")\n    st.markdown("### Latest global index returns")\n    idx_rows = []\n    for _, r in all_index_df.iterrows():\n        t = r["ticker"]\n        if t in prices.columns:\n            ret = prices[t].pct_change(min(20, max(1, len(prices)//5))).dropna()\n            idx_rows.append({"region": r["region"], "name": r["name"], "ticker": t, "recent_return": float(ret.iloc[-1]) if len(ret) else np.nan})\n    st.dataframe(pd.DataFrame(idx_rows), use_container_width=True)\n\nwith tabs[4]:\n    st.subheader("Geopolitical Materials News")\n    st.metric("Geopolitical Materials Risk", geo_state, f"score {geo_score:.2f}")\n    if not geo_theme_df.empty:\n        st.markdown("### Theme mentions")\n        st.dataframe(geo_theme_df, use_container_width=True)\n    if news_df.empty:\n        st.warning("No GDELT news returned. Try a simpler query.")\n    else:\n        for _, r in news_df.head(12).iterrows():\n            st.markdown(f"**{r[\'title\']}**  \\n{r.get(\'domain\',\'\')} — {r.get(\'seendate\',\'\')}  \\n{r[\'url\']}")\n\nwith tabs[5]:\n    st.subheader("Regime Detection")\n    st.metric("Current regime", regime)\n    regime_cols = [c for c in features.columns if c.startswith("FAMILY_") or c.startswith("REGIME_") or c.startswith("GCMSI_")]\n    st.line_chart(features[regime_cols])\n    st.markdown("### Regime logic")\n    st.write("""\n- **Risk-off industrial stress**: GCMSI and VIX stress are both high.\n- **Energy-cost shock**: oil/gas family stress is high.\n- **USD / commodity pressure**: USD pressure is high while material stress is elevated.\n- **Industrial slowdown**: steel/critical-material stress is weak.\n- **Commodity shock**: global materials stress is elevated without full risk-off confirmation.\n""")\n\nwith tabs[6]:\n    st.subheader("Validation / Toy Backtest")\n    if pred_df.empty:\n        st.warning("No validation available.")\n    else:\n        st.dataframe(pred_df[["asset","test_corr","rmse","train_rows","test_rows","confidence_0_1"]], use_container_width=True)\n        asset_bt = st.selectbox("Backtest asset", list(test_curves.keys()))\n        bt = test_curves[asset_bt]\n        if "equity" in bt:\n            st.line_chart(bt["equity"])\n            st.caption("Toy sign backtest only. No transaction costs, slippage, borrow, liquidity, or capacity controls.")\n\nwith tabs[7]:\n    st.subheader("Raw Price Data")\n    st.dataframe(prices.tail(50), use_container_width=True)\n    st.subheader("Feature Data")\n    st.dataframe(features.tail(50), use_container_width=True)\n    st.subheader("Feature Metadata")\n    st.dataframe(feature_meta, use_container_width=True)\n\nst.divider()\nst.caption("Data: Yahoo Finance via yfinance + optional GDELT news query. Research demonstration only; not investment advice.")\n')
